WITH rnp AS (SELECT DISTINCT ID FROM Laboratory WHERE CAST(RNP AS REAL) >= 16),
gpt AS (SELECT ID, MAX(CASE WHEN GPT < 60 THEN GPT END) AS max_normal_gpt, SUM(CASE WHEN GPT >= 60 THEN 1 ELSE 0 END) AS n_high FROM Laboratory GROUP BY ID)
SELECT p.Birthday FROM Patient AS p JOIN rnp ON rnp.ID = p.ID JOIN gpt AS g ON g.ID = p.ID WHERE g.n_high = 0 AND g.max_normal_gpt IS NOT NULL ORDER BY g.max_normal_gpt DESC, p.ID LIMIT 3;

WITH base AS (
  SELECT p.player_api_id, pa.defensive_work_rate AS r
  FROM Player AS p JOIN Player_Attributes AS pa ON pa.player_api_id = p.player_api_id
  WHERE CAST(SUBSTR(p.birthday, 1, 4) AS INTEGER) >= 1991
), rated AS (
  SELECT player_api_id, MAX(CASE WHEN r = 'high' THEN 1 ELSE 0 END) AS any_high
  FROM base WHERE r IN ('low', 'medium', 'high') GROUP BY player_api_id
)
SELECT ROUND(100.0 * SUM(any_high) / COUNT(*), 2) AS pct_high FROM rated;

WITH cohort AS (SELECT p.ID, p.SEX FROM Patient AS p WHERE p.Admission = '-' AND EXISTS (SELECT 1 FROM Laboratory AS l WHERE l.ID = p.ID AND l.HGB < 10)),
peaks AS (SELECT c.ID, c.SEX, MAX(CAST(l.RNP AS REAL)) AS highest_rnp FROM cohort AS c JOIN Laboratory AS l ON l.ID = c.ID GROUP BY c.ID, c.SEX)
SELECT ID, SEX, highest_rnp FROM peaks WHERE highest_rnp = (SELECT MAX(highest_rnp) FROM peaks) ORDER BY ID;
